-- 3. CARGA DE LEITURAS DE CONTADORES E HISTORICO DE COPIAS (MARCO A AGOSTO 2026)

-- 4. ATUALIZAR ULTIMO CONTADOR CONHECIDO NAS INSTALACOES
UPDATE `instalacao_impressora` inst JOIN (SELECT `impressora_id`, MAX(`leitura_mono_atual`) as max_mono, MAX(`data_leitura`) as max_data FROM `leitura_contador` GROUP BY `impressora_id`) l ON inst.`impressora_id` = l.`impressora_id` SET inst.`ultimo_contador_mono` = l.max_mono, inst.`data_ultima_leitura` = l.max_data WHERE inst.`status` = 'ATIVA';